CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, department VARCHAR(100) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS incidents (id BIGINT AUTO_INCREMENT PRIMARY KEY, legacy_id VARCHAR(100) UNIQUE, type VARCHAR(40) NOT NULL, location VARCHAR(200) NOT NULL, occurred_at VARCHAR(30) NOT NULL, severity VARCHAR(20) NOT NULL, description TEXT NOT NULL, population INT NOT NULL DEFAULT 0, priority VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, primary_department VARCHAR(100) NOT NULL DEFAULT '', supporting_department VARCHAR(100) NOT NULL DEFAULT '', resource VARCHAR(200) NOT NULL DEFAULT '', created_by BIGINT NOT NULL, version INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS shelters (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, location VARCHAR(200) NOT NULL, capacity INT NOT NULL, occupied INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS evacuations (id BIGINT AUTO_INCREMENT PRIMARY KEY, incident_id BIGINT NOT NULL, shelter_id BIGINT NOT NULL, people INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (incident_id) REFERENCES incidents(id), FOREIGN KEY (shelter_id) REFERENCES shelters(id), FOREIGN KEY (created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS alerts (id BIGINT AUTO_INCREMENT PRIMARY KEY, incident_id BIGINT NOT NULL, message TEXT NOT NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (incident_id) REFERENCES incidents(id), FOREIGN KEY (created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS acknowledgements (alert_id BIGINT NOT NULL, user_id BIGINT NOT NULL, acknowledged_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(alert_id,user_id), FOREIGN KEY(alert_id) REFERENCES alerts(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor BIGINT NOT NULL, action VARCHAR(40) NOT NULL, details VARCHAR(255) NOT NULL, event_time VARCHAR(40) NOT NULL, signature VARCHAR(100) NOT NULL, FOREIGN KEY(actor) REFERENCES users(id));
